<?= ff('select', 'category', 'pol.category', $f['category'], ['options' => opts(\App\Controllers\PolicyController::CATEGORIES, fn($x) => t('enum.pcat.' . $x), null) ?: [], 'blank_label' => 'common.all']) ?>
<?= ff('select', 'status', 'pol.status', $f['status'], ['options' => opts(['draft', 'approved', 'retired'], fn($x) => t('enum.pstatus.' . $x), null) ?: [], 'blank_label' => 'common.all']) ?>
<?php $lv = []; foreach (\App\Support\Framework::LEVELS as $l) { $lv[$l] = t('enum.doclevel.' . $l); } ?><?= ff('select', 'level', 'docs.level', $f['level'], ['options' => $lv, 'blank_label' => 'common.all']) ?>
<?= ff('select', 'section', 'docs.section', $f['section'], ['options' => opts(\App\Support\Framework::SECTIONS, fn($x) => t('enum.rmsec.' . $x), null) ?: [], 'blank_label' => 'common.all']) ?>
<?= ff('select', 'classification', 'docs.classification', $f['classification'], ['options' => opts(\App\Support\Framework::CLASSIFICATIONS, fn($x) => t('enum.cls.' . $x), null) ?: [], 'blank_label' => 'common.all']) ?>
