<div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('pol.id')) ?></th><th><?= e(t('pol.name')) ?></th><th><?= e(t('pol.category')) ?></th><th><?= e(t('docs.classification')) ?></th><th><?= e(t('pol.owner')) ?></th><th><?= e(t('pol.current_version')) ?></th><th><?= e(t('pol.next_review')) ?></th><th><?= e(t('pol.status')) ?></th></tr></thead><tbody>
