<td class="nowrap"><?= e(fdate($p['next_review_date']) ?: '—') ?><?= $late ? ' <span class="badge danger">' . e(t('risk.overdue')) . '</span>' : '' ?></td><td><?= status_badge($p['status']) ?></td></tr><?php endforeach; ?></tbody></table></div>
